import numpy as np
from collections import Counter, deque
def clusters(a,bg):
    H,W=a.shape; seen=np.zeros_like(a,bool); out=[]
    for i in range(H):
        for j in range(W):
            if a[i,j]!=bg and not seen[i,j]:
                col=a[i,j]; q=deque([(i,j)]); seen[i,j]=1; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and a[ny,nx]==col:
                            seen[ny,nx]=1; q.append((ny,nx))
                out.append((col,cells))
    return out

def apply_rule(g, fillfn):
    a=np.array(g); out=a.copy()
    bg=Counter(a.flatten()).most_common(1)[0][0]
    for col,cells in clusters(a,bg):
        if len(cells)>1:
            r1,r2=min(y for y,x in cells),max(y for y,x in cells)
            c1,c2=min(x for y,x in cells),max(x for y,x in cells)
            box=[(y,x) for y in range(r1,r2+1) for x in range(c1,c2+1)]
            for y,x in box:
                if a[y,x]!=col and a[y,x]!=bg and fillfn(a,col,cells,r1,r2,c1,c2,y,x,bg):
                    out[y,x]=col
    # singles -> bg
    for col,cells in clusters(out,bg):
        if len(cells)==1: out[cells[0]]=bg
    return out

