def R_rowcol1(a,col,cells,r1,r2,c1,c2,y,x,bg): return R_row1(a,col,cells,r1,r2,c1,c2,y,x,bg) and R_col1(a,col,cells,r1,r2,c1,c2,y,x,bg)
def R_unique_total(a,col,cells,r1,r2,c1,c2,y,x,bg):
    return sum(1 for yy in range(r1,r2+1) for xx in range(c1,c2+1) if a[yy,xx]!=col)==1
def R_enclosed(a,col,cells,r1,r2,c1,c2,y,x,bg):
    H,W=a.shape
    L = x>0 and a[y,x-1]==col; R_=x<W-1 and a[y,x+1]==col
    U = y>0 and a[y-1,x]==col; D_=y<H-1 and a[y+1,x]==col
    return (L and R_) or (U and D_)
def R_row1_or_col1(a,col,cells,r1,r2,c1,c2,y,x,bg): return R_row1(a,col,cells,r1,r2,c1,c2,y,x,bg) or R_col1(a,col,cells,r1,r2,c1,c2,y,x,bg)

